import{_ as e,o as r,c as a,ah as d}from"./chunks/framework.DjU4PSOm.js";const u=JSON.parse('{"title":"어린이 재난 대응 앱 비즈니스 모델(BM)","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-11-14T00:00:00.000Z"},"headers":[{"level":2,"title":"무료 vs 유료","slug":"무료-vs-유료","link":"#무료-vs-유료","children":[]},{"level":2,"title":"수익원","slug":"수익원","link":"#수익원","children":[]},{"level":2,"title":"차별점","slug":"차별점","link":"#차별점","children":[]},{"level":2,"title":"확인 필요","slug":"확인-필요","link":"#확인-필요","children":[]}],"relativePath":"computer/project/AWS-PBL/01. 비즈니스 모델 (2026-11-14).md","filePath":"computer/project/AWS-PBL/01. 비즈니스 모델 (2026-11-14).md"}'),l={name:"computer/project/AWS-PBL/01. 비즈니스 모델 (2026-11-14).md"};function o(i,t,n,s,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="어린이-재난-대응-앱-비즈니스-모델-bm" tabindex="-1">어린이 재난 대응 앱 비즈니스 모델(BM) <a class="header-anchor" href="#어린이-재난-대응-앱-비즈니스-모델-bm" aria-label="Permalink to &quot;어린이 재난 대응 앱 비즈니스 모델(BM)&quot;">​</a></h1><blockquote><p>AWS Career Launchpad PBL 팀 프로젝트. 원본 문서: <a href="https://claude.ai/artifact/GQAk5mknfgXPq9QPxMfbk5" target="_blank" rel="noreferrer">Claude Docs</a></p></blockquote><p>재난 대응 기능은 모두 무료로 두고, 돈은 보호자 구독·기관·제휴에서 번다. 아이에게는 결제나 광고를 띄우지 않는다.</p><h2 id="무료-vs-유료" tabindex="-1">무료 vs 유료 <a class="header-anchor" href="#무료-vs-유료" aria-label="Permalink to &quot;무료 vs 유료&quot;">​</a></h2><table tabindex="0"><thead><tr><th>기능</th><th>무료</th><th>패밀리 플랜 (월 2,900원)</th></tr></thead><tbody><tr><td>재난 대응 (쉬운 말 문자, 행동 카드, 괜찮아요/도와줘요)</td><td>O</td><td>O</td></tr><tr><td>연결 인원</td><td>아이 1명 + 보호자 1명</td><td>여러 명 (조부모·돌봄 선생님 포함)</td></tr><tr><td>훈련 콘텐츠</td><td>지진·화재</td><td>듀오링고식 전체 코스 (매일 미션, 연속 훈련 스트릭, 대원 등급)</td></tr><tr><td>보호자 리포트</td><td>응답 기록</td><td>훈련 진도 + 가족 비상 계획서</td></tr></tbody></table><h2 id="수익원" tabindex="-1">수익원 <a class="header-anchor" href="#수익원" aria-label="Permalink to &quot;수익원&quot;">​</a></h2><table tabindex="0"><thead><tr><th>고객</th><th>파는 것</th></tr></thead><tbody><tr><td>보호자</td><td>패밀리 플랜 구독</td></tr><tr><td>학교·유치원</td><td>반 단위 훈련 + 교사용 안전 확인 화면 (연간 라이선스)</td></tr><tr><td>지자체</td><td>관내 초등학생 무료 배포 사업</td></tr><tr><td>통신사·보험사</td><td>키즈폰·어린이보험 부가서비스 제휴</td></tr></tbody></table><h2 id="차별점" tabindex="-1">차별점 <a class="header-anchor" href="#차별점" aria-label="Permalink to &quot;차별점&quot;">​</a></h2><ul><li><strong>정부 재난문자</strong>는 어른 말투다. 우리는 아이 눈높이로 바꾼다.</li><li><strong>자녀 관리 앱</strong>은 사용 시간·위치 통제가 중심이다. 우리는 재난 순간의 행동과 보호자 연결에 집중한다.</li><li><strong>학교 안전 교육</strong>은 일회성이다. 우리는 평소 훈련과 실제 대응이 한 앱에서 이어진다.</li><li><strong>게임형 안전교육 앱</strong>(<a href="https://apps.apple.com/us/app/%EC%A7%80%EC%A7%84%EC%95%88%EC%A0%84%EA%B5%90%EC%9C%A1-%EC%96%B4%EB%A6%B0%EC%9D%B4-%EC%95%88%EC%A0%84/id1160733919?l=ko" target="_blank" rel="noreferrer">BabyBus 지진안전교육</a>, 적십자 <a href="https://www.slj.com/story/prepare-kids-for-emergencies-with-monster-guard" target="_blank" rel="noreferrer">Monster Guard</a>)은 교육만 한다. 우리는 실제 재난문자 수신과 보호자 연결까지 이어진다.</li></ul><h2 id="확인-필요" tabindex="-1">확인 필요 <a class="header-anchor" href="#확인-필요" aria-label="Permalink to &quot;확인 필요&quot;">​</a></h2><ul><li>가격 근거: 보호자 설문으로 검증</li><li>학교 재난안전 교육 의무 기준 (교육부 자료)</li></ul>',11)])])}const p=e(l,[["render",o]]);export{u as __pageData,p as default};
